		check(values().getFormat().getVersion() == format, "owner must preserve the independently produced dialect");
		add(List.of(VALUES.createStatement(VALUES.createIRI("urn:lifetime:keeper"), PREDICATE,
				VALUES.createLiteral("keeper"), CONTEXT)));
