	private static long nativeMapSize(TxnManager manager) throws Exception {
		return manager.doWith((stack, transaction) -> {
			MDBEnvInfo information = MDBEnvInfo.malloc(stack);
			E(mdb_env_info(mdb_txn_env(transaction), information));
			return information.me_mapsize();
		});
	}

	private byte[] nativeGet(String database, byte[] bytes) throws Exception {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			var pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			long environment = pointer.get(0);
			try {
				E(mdb_env_set_maxdbs(environment, 32));
				E(mdb_env_open(environment, directory.resolve("values").toString(), MDB_NOTLS | MDB_RDONLY, 0664));
				return LmdbUtil.readTransaction(environment, (inner, transaction) -> {
					var handle = inner.mallocInt(1);
					E(mdb_dbi_open(transaction, database, 0, handle));
					var key = MDBVal.calloc(inner).mv_data(inner.bytes(bytes));
					var data = MDBVal.calloc(inner);
					int result = mdb_get(transaction, handle.get(0), key, data);
					if (result == MDB_NOTFOUND) {
						return null;
					}
					E(result);
					byte[] answer = new byte[data.mv_data().remaining()];
					data.mv_data().get(answer);
					return answer;
				});
			} finally {
				mdb_env_close(environment);
			}
		}
	}

	private static byte[] unsigned(long value) {
		ByteBuffer buffer = ByteBuffer.allocate(9);
		Varint.writeUnsigned(buffer, value);
		return Arrays.copyOf(buffer.array(), buffer.position());
	}

	private static void expectResizeAbort(Runnable read) {
		try {
			read.run();
		} catch (SailException failure) {
			check(failure.getMessage().contains("SNAPSHOT") && failure.getMessage().contains("retry"),
					"resize must report the explicit SNAPSHOT retry contract: " + failure);
			return;
		}
		throw new AssertionError("Invalidated snapshot served a cached or renewed read after actual native growth");
	}

	private static void check(boolean condition, String message) {
		if (!condition) {
			throw new AssertionError(message);
		}
	}
